title:
// ❌ 멱등성 없음
let count = 0
function Counter() {
  count++  // 렌더링마다 달라짐
  return <div>{count}</div>
}

// ✅ 멱등성 있음
function Counter({ value }) {
  return <div>{value}</div>
}

